if(state.page==='ofertas')c.innerHTML=`<div class="heading"><div><small class="kicker">ATENDIMENTO AO CLIENTE</small><h1>Monte uma oferta.</h1><p>Informe as datas, selecione imóveis e gere uma mensagem pronta para revisar e copiar.</p></div></div><div class="two-col"><section class="panel"><h2>O que o cliente procura?</h2><form id="offer" class="form"><label>Nome do cliente (opcional)</label><input name="cliente" placeholder="Nome do cliente"><div class="row"><div><label>Entrada</label><input name="inicio" type="date" required></div><div><label>Saída</label><input name="fim" type="date" required></div></div><label>Quantidade de hóspedes</label><input name="hospedes" type="number" min="1" value="2" required><label>Escolha os imóveis</label><div class="choices">${state.homes.filter(p=>p.ativo!==false).map(p=>`<label class="choice"><input type="checkbox" name="home" value="${p.id}"><span><b>${safe(p.titulo)}</b><small>${p.capacidade||0} hóspedes</small></span></label>`).join('')}</div><button class="btn primary full">Gerar mensagem →</button></form></section><section class="panel"><small class="kicker">PRÉVIA DA MENSAGEM</small><h2>Pronta para revisar.</h2><textarea id="message" rows="17" placeholder="Sua mensagem aparecerá aqui…" readonly>${safe(state.message)}</textarea><button id="copy" class="btn secondary full" ${state.message?'':'disabled'}>Copiar mensagem</button><button id="save-offer" class="btn primary full" disabled>Salvar oferta</button><p class="fine">A disponibilidade será indicada como pendente de confirmação.</p></section></div>`;
