 popup.document.open();
 popup.document.write('<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+title+'</title><style>'+
 '*{box-sizing:border-box}body{margin:0;color:#17345b;font:14px/1.55 Arial,sans-serif}h1,h2,p{margin-top:0}h1{font-size:29px;line-height:1.15;margin-bottom:9px}h2{font-size:18px;margin-bottom:10px}.muted{color:#697789}.eyebrow{text-transform:uppercase;letter-spacing:2px;font-size:10px;color:#9b804a;font-weight:bold}.cover-sheet{min-height:265mm;display:flex;flex-direction:column;page-break-after:always}.brand{font-size:17px;letter-spacing:2px;font-weight:bold;margin-bottom:18px}.cover-photo{height:115mm;background:#f2efe8;display:flex;align-items:center;justify-content:center;overflow:hidden;margin:18px 0}.cover-photo img{width:100%;height:100%;object-fit:cover}.no-photo{color:#8993a0}.facts{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:12px 0 18px}.fact{border-top:1px solid #d9d4c9;padding-top:8px}.fact b{display:block;font-size:16px}.amenities{display:flex;flex-wrap:wrap;gap:8px;margin:12px 0}.amenities span{border:1px solid #ded7c9;border-radius:20px;padding:5px 10px;font-size:12px}.footer{margin-top:auto;padding-top:14px;border-top:1px solid #e1ded7;font-size:10px;color:#78818b}.detail-sheet{padding-top:3mm}.description{white-space:pre-wrap;overflow-wrap:anywhere}.gallery{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:15px}.gallery figure{margin:0;break-inside:avoid}.gallery img{width:100%;height:75mm;object-fit:cover}.gallery figcaption{font-size:10px;color:#697789;margin-top:4px}.video-list{overflow-wrap:anywhere}a{color:#17345b}@page{size:A4;margin:15mm}@media print{.cover-sheet{min-height:267mm}}'+
 '</style></head><body><main class="cover-sheet"><div class="brand">BancoImob</div><div class="eyebrow">Imóvel para locação por temporada</div><h1>'+title+'</h1><p class="muted">'+safe(p.bairro||'Bairro não informado')+'</p><div class="cover-photo">'+(cover?'<img src="'+safe(cover.url)+'" alt="Foto de capa">':'<span class="no-photo">Foto de capa não cadastrada</span>')+'</div><div class="facts"><div class="fact"><span class="muted">Capacidade</span><b>Até '+safe(p.capacidade||'—')+' hóspedes</b></div><div class="fact"><span class="muted">Dormitórios</span><b>'+safe(p.dormitorios??'—')+(p.suites?' · '+safe(p.suites)+' suítes':'')+'</b></div><div class="fact"><span class="muted">Distância da praia</span><b>'+safe(p.distancia_praia===null||p.distancia_praia===undefined?'Não informada':p.distancia_praia+' m')+'</b></div></div>'+(amenities.length?'<div class="amenities">'+amenities.map(x=>'<span>'+safe(x)+'</span>').join('')+'</div>':'')+'<div class="footer">Disponibilidade e condições devem ser confirmadas com o responsável pelo imóvel.</div></main><section class="detail-sheet"><div class="eyebrow">Detalhes do imóvel</div><h2>'+title+'</h2><p class="description">'+safe(p.descricao||'Descrição não cadastrada.')+'</p>'+(gallery?'<h2>Fotos do imóvel</h2><div class="gallery">'+gallery+'</div>':'')+(videoList?'<h2 style="margin-top:20px">Vídeos do imóvel</h2><ul class="video-list">'+videoList+'</ul>':'')+'<div class="footer">BancoImob · Informações do imóvel para consulta comercial.</div></section></body></html>');
