async function deleteHome(id,button){
 const p=state.homes.find(home=>home.id===id);if(!p)return;
 if(!confirm('Excluir "'+p.titulo+'"? O imóvel, seus preços, fotos e vínculos de ofertas serão removidos. Esta ação não pode ser desfeita.'))return;
 button.disabled=true;button.textContent='Excluindo…';
 const photoRows=state.photos.filter(photo=>photo.imovel_id===id);
 const storagePaths=photoRows.map(photo=>{try{const u=new URL(photo.url);const prefix='/storage/v1/object/public/mare-imoveis/';if(!u.pathname.includes(prefix))return '';return decodeURIComponent(u.pathname.split(prefix)[1]||'')}catch{return ''}}).filter(Boolean);
 const tasks=[
  ['vínculos de ofertas',()=>db.from('mare_oferta_imoveis').delete().eq('imovel_id',id)],
  ['fotos',()=>db.from('mare_fotos_imovel').delete().eq('imovel_id',id)],
  ['preços',()=>db.from('mare_precos_imovel').delete().eq('imovel_id',id)],
  ['imóvel',()=>db.from('mare_imoveis').delete().eq('id',id)]
 ];
 for(const [label,run] of tasks){const result=await run();if(result.error){say('Não foi possível concluir a exclusão ('+label+'): '+result.error.message,true);button.disabled=false;button.textContent='Excluir';return}}
 if(storagePaths.length){const storage=await db.storage.from('mare-imoveis').remove(storagePaths);if(storage.error)say('Imóvel excluído, mas algumas fotos antigas podem permanecer no armazenamento.',true)}
 if(state.selectedHomeId===id){state.selectedHomeId=null;state.selectedHomeAlias=null}
 say('Imóvel excluído.');await load();
}
function cards(list){
 if(!list.length)return '<div class="empty">Nenhum imóvel encontrado. Cadastre uma casa para começar.</div>';
 return '<div class="cards">'+list.map(p=>{
  const media=state.photos.find(f=>f.imovel_id===p.id&&f.capa&&!mediaIsVideo(f))||state.photos.find(f=>f.imovel_id===p.id&&!mediaIsVideo(f))||state.photos.find(f=>f.imovel_id===p.id);
  const cover=media?(mediaIsVideo(media)?'<a class="video-cover" href="'+safe(media.url)+'" target="_blank" rel="noreferrer"><span>▶</span><b>Vídeo do imóvel</b><small>Abrir vídeo ↗</small></a>':'<img src="'+safe(media.url)+'" alt="Foto de '+safe(p.titulo)+'" style="width:100%;height:100%;object-fit:cover">'):'⌂<small>FOTO OU VÍDEO DO IMÓVEL</small>';
  return '<article class="home-card"><div class="cover">'+cover+'<span class="status">'+({disponivel:'Disponível',reservado:'Reservado',indisponivel:'Indisponível',a_confirmar:'A confirmar'})[p.disponibilidade_status||'a_confirmar']+'</span></div><div class="card-body"><h3>'+safe(p.titulo)+'</h3><p>'+safe(p.bairro||'Localização não informada')+'</p><div class="facts">'+(p.dormitorios||0)+' dormitórios'+(p.suites?' · '+p.suites+' suítes':'')+' · '+(p.capacidade||0)+' hóspedes · '+(p.distancia_praia??'—')+' m da praia</div><div class="card-foot"><b>'+priceLabel(p.id)+'</b><div class="card-actions"><button data-view-prices="'+p.id+'">Consultar valores</button><button data-edit="'+p.id+'">Editar</button><button data-export-pdf="'+p.id+'">Exportar PDF</button><button class="danger-text" data-delete-home="'+p.id+'">Excluir</button></div></div></div></article>';
 }).join('')+'</div>';
}
function priceLabel(id){const p=state.prices.find(x=>x.imovel_id===id&&x.tipo==='diaria'&&isBasePrice(x));return p?money(p.valor)+'/ diária':'Ver preços';}
